def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    specials = set()

    # Mark isolated cells whose color occurs only as a one-cell component.
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            same = any(
                0 <= r + dr < h and 0 <= c + dc < w
                and g[r + dr][c + dc] == color
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
            )
            if not same:
                specials.add((r, c))

    for r, c in specials:
        counts = {}
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                v = g[nr][nc]
                if (nr, nc) not in specials:
                    counts[v] = counts.get(v, 0) + 1
        if counts:
            g[r][c] = max(counts, key=counts.get)
    return g
