def transform(grid):
    from collections import deque, Counter

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    singleton_cells = []

    # Find connected components; isolated single-cell components are noise.
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if len(comp) == 1:
                singleton_cells.append(comp[0])

    # Replace each isolated cell with the most common surrounding color
    # in its 8-cell neighborhood.
    for r, c in singleton_cells:
        counts = Counter(
            grid[rr][cc]
            for rr in range(max(0, r - 1), min(h, r + 2))
            for cc in range(max(0, c - 1), min(w, c + 2))
            if (rr, cc) != (r, c)
        )
        if counts:
            out[r][c] = counts.most_common(1)[0][0]

    return out
